-- 1117: Bar and Tube - Saw cut, version 2 -- a bundle shares the index and the handling, not the cutting.
--
-- GENERATED by scripts/generate-bar-tube-calculators-migration.ts from
-- src/modules/bom-items/costing/bar-tube/calculators/bar-tube-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Migration 1091 divided the whole saw cycle by the parts in a bundle: (cut + index + load and unload) / parts per bundle. A blade removes
-- metal at its cutting rate however many bars lie under it, so a bundle of n bars takes n times the cut of one: each part still pays for
-- its own section. Dividing the cut by the bundle made a full bundle of 18 bars saw about 18 times faster than the saw can cut.
-- Version 2 shares only what the bundle does share (one index, one load and unload) and cuts every part's section; the engine reads the
-- cutting rate at the bundle's width in the cut, and never bundles more bars than the batch needs.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Bar and Tube Fabrication catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Bar and Tube - Saw cut
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Bar and Tube - Saw cut$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description, version)
    VALUES (NULL, $q$Bar and Tube - Saw cut$q$, 'process', 'single', false, true, true, $q$Cutting the stock to length: the section's metal area (more on an angled cut) at the saw's cutting rate for the material's cut-code family and the width in the cut (lookup saw_cut_rate; a bundle is cut as one section, at the bundle's width), the stock indexed by one part length at the saw's axial feed, the load and unload of each bundle. Bars cut in a bundle (as the saw's capacity, maxPartsPerBundle and the bars the batch needs allow) share the index and the handling; each part's own section is still cut.$q$, 2)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Cutting the stock to length: the section's metal area (more on an angled cut) at the saw's cutting rate for the material's cut-code family and the width in the cut (lookup saw_cut_rate; a bundle is cut as one section, at the bundle's width), the stock indexed by one part length at the saw's axial feed, the load and unload of each bundle. Bars cut in a bundle (as the saw's capacity, maxPartsPerBundle and the bars the batch needs allow) share the index and the handling; each part's own section is still cut.$q$, version = 2, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Cut Area$q$, $q$Cut Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Cutting Rate$q$, $q$Cutting Rate (mm²/min)$q$, $q$number$q$, $q$mm²/min$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cut Length$q$, $q$Cut Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Axial Feed Rate$q$, $q$Axial Feed Rate (mm/s)$q$, $q$number$q$, $q$mm/s$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Load and Unload$q$, $q$Load and Unload (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Parts per Bundle$q$, $q$Parts per Bundle$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Cuts per Part$q$, $q$Cuts per Part$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Cut Time$q$, $q$Cut Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Cuts per Part} * {Cut Area} / {Cutting Rate} * 60$q$, 9, false),
    (v_id, $q$Index Time$q$, $q$Index Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Cut Length} / {Axial Feed Rate}$q$, 10, false),
    (v_id, $q$Handling per Part$q$, $q$Handling per Part (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Index Time} + {Load and Unload}) / {Parts per Bundle}$q$, 11, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$({Cut Time} + {Handling per Part}) * {Cycle Time Factor}$q$, 12, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Bar and Tube - Saw cut$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Bar and Tube Fabrication$q$ AND operation IN ($q$Band Saw$q$, $q$Circular Saw$q$, $q$Reciprocating Saw$q$);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Bar and Tube - Saw cut$q$, 12, 3)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Bar and Tube Fabrication$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1117: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
